def solve(line):
    """Parse a CSV line into fields handling quotes and escaped quotes.
    Returns a list of field strings.
    """
    if line == '':
        return ['']
    fields = []
    field = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i+1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field))
                field = []
            elif ch == '"':
                in_quotes = True
            else:
                field.append(ch)
        i += 1
    fields.append(''.join(field))
    return fields

def solve(n):
    """Return the number of prime numbers strictly less than n."""
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)  # True means prime candidate
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    # Count true values
    return sum(sieve)

