def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is given as a two‑element list or tuple ``[start, end]``.
    If ``start`` is greater than ``end`` the interval is interpreted as
    ``[end, start]`` (i.e., we swap them). Meetings may touch at endpoints.
    """
    if not meetings:
        return 0
    intervals = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        try:
            start = int(m[0])
            end = int(m[1])
        except Exception:
            continue
        if start > end:
            start, end = end, start
        intervals.append((start, end))
    if not intervals:
        return 0
    # Sort by finishing time, then start time
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

