def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

def solve(tokens):
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero without using float
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

