def solve(n, edges):
    from collections import defaultdict
    import heapq
    indeg = [0]*n
    adj = defaultdict(list)
    for a,b in edges:
        if a<0 or a>=n or b<0 or b>=n:
            continue
        adj[a].append(b)
        indeg[b]+=1
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order=[]
    while heap:
        u=heapq.heappop(heap)
        order.append(u)
        for v in adj.get(u,[]):
            indeg[v]-=1
            if indeg[v]==0:
                heapq.heappush(heap,v)
    if len(order)!=n:
        return []
    return order

